-- Seeded keto recipe catalog. Generated by scripts/emit-recipe-seed.mjs.
-- Calories are label-style estimates: protein*4 + fat*9 + net carbs*4.
-- Net carbs = total carbs - fiber.

insert into public.recipes (
  name,
  meal_type,
  ingredients,
  calories,
  protein_g,
  fat_g,
  total_carbs_g,
  fiber_g,
  net_carbs_g,
  instructions,
  allergen_tags
) values
  ('Spinach cheddar scramble', 'breakfast', '[{"name":"eggs","quantity":3,"unit":"large"},{"name":"baby spinach","quantity":2,"unit":"cups"},{"name":"cheddar","quantity":1,"unit":"oz"},{"name":"butter","quantity":1,"unit":"tsp"}]'::jsonb, 385, 28, 29, 4, 1, 3, 'Melt butter in a skillet. Soft-scramble the eggs, then fold in spinach and cheddar until just set.', array['eggs', 'dairy']::text[]),
  ('Bacon avocado plate', 'breakfast', '[{"name":"bacon","quantity":3,"unit":"slices"},{"name":"eggs","quantity":2,"unit":"large"},{"name":"avocado","quantity":0.5,"unit":"whole"}]'::jsonb, 406, 22, 34, 8, 5, 3, 'Cook the bacon, fry the eggs in a teaspoon of the rendered fat, and serve with sliced avocado.', array['eggs']::text[]),
  ('Smoked salmon cucumber bites', 'breakfast', '[{"name":"smoked salmon","quantity":3,"unit":"oz"},{"name":"cucumber","quantity":1,"unit":"whole"},{"name":"cream cheese","quantity":2,"unit":"tbsp"},{"name":"fresh dill","quantity":1,"unit":"tsp"}]'::jsonb, 192, 18, 12, 4, 1, 3, 'Spread cream cheese on cucumber rounds, top with smoked salmon, and finish with dill.', array['fish', 'dairy']::text[]),
  ('Sausage and pepper skillet', 'breakfast', '[{"name":"breakfast sausage","quantity":3,"unit":"oz"},{"name":"bell pepper","quantity":1,"unit":"cup"},{"name":"baby spinach","quantity":1,"unit":"cup"},{"name":"olive oil","quantity":1,"unit":"tsp"}]'::jsonb, 318, 16, 26, 7, 2, 5, 'Brown the sausage in olive oil, add pepper, and wilt the spinach. Salt and pepper to taste.', '{}'::text[]),
  ('Coconut flour pancakes', 'breakfast', '[{"name":"coconut flour","quantity":3,"unit":"tbsp"},{"name":"eggs","quantity":2,"unit":"large"},{"name":"heavy cream","quantity":2,"unit":"tbsp"},{"name":"butter","quantity":1,"unit":"tsp"}]'::jsonb, 332, 16, 28, 8, 4, 4, 'Whisk flour, eggs, and cream. Cook small pancakes in butter until the edges set, then flip once.', array['eggs', 'dairy']::text[]),
  ('Greek yogurt almond bowl', 'breakfast', '[{"name":"plain Greek yogurt","quantity":0.75,"unit":"cup"},{"name":"raspberries","quantity":0.25,"unit":"cup"},{"name":"almonds","quantity":1,"unit":"tbsp"}]'::jsonb, 234, 18, 14, 12, 3, 9, 'Spoon whole-milk yogurt into a bowl. Top with raspberries and chopped almonds.', array['dairy', 'nuts']::text[]),
  ('Chia coconut pudding', 'breakfast', '[{"name":"chia seeds","quantity":3,"unit":"tbsp"},{"name":"unsweetened almond milk","quantity":1,"unit":"cup"},{"name":"coconut cream","quantity":2,"unit":"tbsp"},{"name":"cinnamon","quantity":0.25,"unit":"tsp"}]'::jsonb, 202, 6, 18, 14, 10, 4, 'Stir chia, almond milk, coconut cream, and cinnamon. Chill at least 2 hours, overnight if you can.', array['nuts']::text[]),
  ('Mushroom herb omelet', 'breakfast', '[{"name":"eggs","quantity":3,"unit":"large"},{"name":"mushrooms","quantity":1,"unit":"cup"},{"name":"butter","quantity":1,"unit":"tsp"},{"name":"fresh parsley","quantity":1,"unit":"tbsp"}]'::jsonb, 290, 20, 22, 4, 1, 3, 'Saute mushrooms in butter. Add beaten eggs, tilt the pan, and fold when the center is still soft.', array['eggs', 'dairy']::text[]),
  ('Grilled chicken olive salad', 'lunch', '[{"name":"chicken breast","quantity":5,"unit":"oz"},{"name":"romaine","quantity":2,"unit":"cups"},{"name":"cucumber","quantity":0.5,"unit":"whole"},{"name":"tomato","quantity":0.5,"unit":"whole"},{"name":"olive oil","quantity":1,"unit":"tbsp"}]'::jsonb, 322, 35, 18, 8, 3, 5, 'Grill or pan-sear the chicken. Slice it over romaine with cucumber, tomato, olive oil, salt, and lemon.', '{}'::text[]),
  ('Bunless beef bowl', 'lunch', '[{"name":"ground beef","quantity":5,"unit":"oz"},{"name":"romaine","quantity":2,"unit":"cups"},{"name":"tomato","quantity":0.5,"unit":"whole"},{"name":"dill pickle","quantity":1,"unit":"spear"},{"name":"yellow mustard","quantity":1,"unit":"tsp"}]'::jsonb, 342, 32, 22, 6, 2, 4, 'Brown the beef with salt and pepper. Serve over lettuce with tomato, pickle, and mustard.', '{}'::text[]),
  ('Turkey lettuce wraps', 'lunch', '[{"name":"sliced turkey","quantity":4,"unit":"oz"},{"name":"butter lettuce","quantity":4,"unit":"leaves"},{"name":"avocado","quantity":0.25,"unit":"whole"},{"name":"yellow mustard","quantity":1,"unit":"tsp"}]'::jsonb, 232, 28, 12, 6, 3, 3, 'Fill lettuce leaves with turkey, avocado, and mustard. Eat two wraps and save the rest for later if you like.', '{}'::text[]),
  ('Tuna stuffed avocado', 'lunch', '[{"name":"tuna in olive oil","quantity":4,"unit":"oz"},{"name":"avocado","quantity":0.5,"unit":"whole"},{"name":"celery","quantity":1,"unit":"stalk"},{"name":"lemon juice","quantity":1,"unit":"tsp"}]'::jsonb, 356, 32, 24, 9, 6, 3, 'Drain most of the oil, mix tuna with chopped celery and lemon, and spoon it into the avocado half.', array['fish']::text[]),
  ('Shrimp avocado salad', 'lunch', '[{"name":"shrimp","quantity":5,"unit":"oz"},{"name":"mixed greens","quantity":2,"unit":"cups"},{"name":"avocado","quantity":0.25,"unit":"whole"},{"name":"olive oil","quantity":1,"unit":"tbsp"}]'::jsonb, 276, 30, 16, 7, 4, 3, 'Sear shrimp with salt and garlic powder. Toss greens with olive oil and top with shrimp and avocado.', array['shellfish']::text[]),
  ('Chicken Caesar lettuce wraps', 'lunch', '[{"name":"chicken breast","quantity":4,"unit":"oz"},{"name":"romaine","quantity":1.5,"unit":"cups"},{"name":"parmesan","quantity":0.5,"unit":"oz"},{"name":"caesar dressing","quantity":1,"unit":"tbsp"}]'::jsonb, 354, 36, 22, 5, 2, 3, 'Slice cooked chicken over romaine. Add parmesan and a measured spoon of dressing, then wrap in the largest leaves.', array['dairy', 'eggs', 'fish']::text[]),
  ('Egg salad lettuce cups', 'lunch', '[{"name":"eggs","quantity":3,"unit":"large"},{"name":"mayonnaise","quantity":1,"unit":"tbsp"},{"name":"celery","quantity":1,"unit":"stalk"},{"name":"butter lettuce","quantity":3,"unit":"leaves"}]'::jsonb, 308, 20, 24, 4, 1, 3, 'Chop hard-boiled eggs with mayonnaise, celery, salt, and pepper. Spoon into lettuce cups.', array['eggs']::text[]),
  ('Pesto chicken zucchini noodles', 'lunch', '[{"name":"chicken thigh","quantity":4,"unit":"oz"},{"name":"zucchini","quantity":2,"unit":"cups"},{"name":"basil pesto","quantity":2,"unit":"tbsp"}]'::jsonb, 390, 34, 26, 8, 3, 5, 'Sear the chicken. Toss spiralized zucchini in the warm pan just until soft, then stir in pesto.', array['dairy', 'nuts']::text[]),
  ('Ribeye and broccoli', 'dinner', '[{"name":"ribeye steak","quantity":6,"unit":"oz"},{"name":"broccoli","quantity":1.5,"unit":"cups"},{"name":"olive oil","quantity":1,"unit":"tbsp"}]'::jsonb, 508, 42, 36, 8, 4, 4, 'Season the steak with salt and sear to your preferred doneness. Roast broccoli in olive oil on the side.', '{}'::text[]),
  ('Chicken thighs with olives', 'dinner', '[{"name":"chicken thigh","quantity":6,"unit":"oz"},{"name":"green olives","quantity":8,"unit":"olives"},{"name":"baby spinach","quantity":2,"unit":"cups"},{"name":"olive oil","quantity":1,"unit":"tsp"}]'::jsonb, 452, 38, 32, 5, 2, 3, 'Brown the thighs, add olives and a splash of water, cover 8 minutes, then wilt spinach into the pan.', '{}'::text[]),
  ('Pork chops and roasted cauliflower', 'dinner', '[{"name":"pork chop","quantity":6,"unit":"oz"},{"name":"cauliflower","quantity":2,"unit":"cups"},{"name":"olive oil","quantity":1,"unit":"tbsp"}]'::jsonb, 396, 40, 24, 8, 3, 5, 'Roast cauliflower in olive oil at 425 F. Pan-sear the chop with salt, pepper, and garlic powder.', '{}'::text[]),
  ('Ginger beef and broccoli', 'dinner', '[{"name":"sirloin steak","quantity":5,"unit":"oz"},{"name":"broccoli","quantity":1.5,"unit":"cups"},{"name":"fresh ginger","quantity":1,"unit":"tsp"},{"name":"olive oil","quantity":1,"unit":"tbsp"}]'::jsonb, 378, 40, 22, 9, 4, 5, 'Slice the sirloin thin. Stir-fry with broccoli, ginger, salt, and olive oil until the beef is just cooked.', '{}'::text[]),
  ('Lamb chops and green beans', 'dinner', '[{"name":"lamb chops","quantity":5,"unit":"oz"},{"name":"green beans","quantity":1.5,"unit":"cups"},{"name":"olive oil","quantity":1,"unit":"tbsp"}]'::jsonb, 434, 36, 30, 8, 3, 5, 'Sear chops with salt and pepper. Saute green beans in olive oil until blistered and still bright.', '{}'::text[]),
  ('Garlic butter salmon and asparagus', 'dinner', '[{"name":"salmon","quantity":6,"unit":"oz"},{"name":"asparagus","quantity":8,"unit":"spears"},{"name":"butter","quantity":1,"unit":"tbsp"},{"name":"garlic","quantity":1,"unit":"clove"}]'::jsonb, 424, 40, 28, 6, 3, 3, 'Roast salmon and asparagus at 400 F. Spoon garlic melted in butter over the fish before serving.', array['fish', 'dairy']::text[]),
  ('Lemon butter cod', 'dinner', '[{"name":"cod","quantity":6,"unit":"oz"},{"name":"zucchini","quantity":1,"unit":"cup"},{"name":"butter","quantity":1,"unit":"tbsp"},{"name":"lemon juice","quantity":1,"unit":"tbsp"}]'::jsonb, 300, 36, 16, 5, 2, 3, 'Bake cod until it flakes. Warm zucchini in butter and lemon and spoon it beside the fish.', array['fish', 'dairy']::text[]),
  ('Creamy Tuscan chicken', 'dinner', '[{"name":"chicken thigh","quantity":6,"unit":"oz"},{"name":"heavy cream","quantity":0.25,"unit":"cup"},{"name":"baby spinach","quantity":2,"unit":"cups"},{"name":"parmesan","quantity":0.5,"unit":"oz"},{"name":"sun-dried tomatoes","quantity":2,"unit":"tbsp"}]'::jsonb, 494, 42, 34, 7, 2, 5, 'Sear the thighs, then simmer cream, spinach, parmesan, and chopped sun-dried tomatoes for a few minutes.', array['dairy']::text[]),
  ('Cucumber guacamole cups', 'snack', '[{"name":"cucumber","quantity":0.5,"unit":"whole"},{"name":"avocado","quantity":0.5,"unit":"whole"},{"name":"lime juice","quantity":1,"unit":"tsp"}]'::jsonb, 128, 2, 12, 9, 6, 3, 'Mash avocado with lime and salt. Spoon it into cucumber cups cut from the other half.', '{}'::text[]),
  ('Olive and pepperoni plate', 'snack', '[{"name":"green olives","quantity":10,"unit":"olives"},{"name":"pepperoni","quantity":1,"unit":"oz"}]'::jsonb, 180, 7, 16, 3, 1, 2, 'Set olives and pepperoni on a plate. No cooking. Eat it cold.', '{}'::text[]),
  ('Cheddar crisps', 'snack', '[{"name":"cheddar","quantity":1.5,"unit":"oz"}]'::jsonb, 170, 10, 14, 1, 0, 1, 'Mound small piles of shredded cheddar on parchment. Bake at 400 F until the edges brown, then cool until crisp.', array['dairy']::text[]),
  ('Roasted almonds', 'snack', '[{"name":"almonds","quantity":1,"unit":"oz"}]'::jsonb, 162, 6, 14, 6, 3, 3, 'Measure one ounce. A pinch of salt is plenty if they are not already salted.', array['nuts']::text[]),
  ('Hard-boiled eggs', 'snack', '[{"name":"eggs","quantity":2,"unit":"large"}]'::jsonb, 142, 12, 10, 1, 0, 1, 'Simmer eggs for 10 minutes, chill, peel, and season with salt.', array['eggs']::text[]),
  ('Macadamia nuts', 'snack', '[{"name":"macadamia nuts","quantity":1,"unit":"oz"}]'::jsonb, 205, 2, 21, 4, 2, 2, 'Measure one ounce. They are rich, so stop at the portion.', array['nuts']::text[])
